(function () {
  'use strict';
  const M = globalThis.RentalPrototype;
  const root = document.getElementById('rental-workflow');
  const mini = root.querySelector('#inv-mini'), admin = root.querySelector('#inv-admin');
  const content = mini.querySelector('#im-content'), main = admin.querySelector('#ia-main');
  const mLayer = mini.querySelector('#im-sheet-layer'), aLayer = admin.querySelector('#ia-modal-layer');
  const names = { view:'查看', control:'启停', frequency:'调频', reset:'复位' };
  const pages = { devices:'设备管理', leases:'租赁合同', reports:'统计报表', income:'收款明细', backup:'用户数据与备份', permissions:'用户授权', reminders:'到期与提醒', logs:'操作记录' };
  let store = M.seed();
  let ui = { mode:'admin', user:'admin', screen:'devices', page:'backup', selected:'05', filter:'all', query:'', adminFilter:'all', adminQuery:'', scanRaw:'HN|VF-22|DEMO4G001005', historyView:'chart', metric:'frequency', density:16, incomeMonth:'2026-10', incomeKind:'all', incomeAvailable:true, mobileInventoryAvailable:true, reportsAvailable:true, userBackupAvailable:true, reportDimension:'device', reportMonth:'all', incomeScope:null, incomeFromReport:false };
  let scanResult = null, scanError = '', scanAdded = false, inventoryDraft = null, contractDraft = null, permissionDraft = null, permissionDevice = null, pendingLeave = null;
  let toastTimer, commandBusy = false, renewDevice = null;
  const stateWriter = Date.now().toString(36) + Math.random().toString(36).slice(2);
  let stateRevision = 0;
  const icon = name => '<i data-lucide="' + name + '" aria-hidden="true"></i>';
  const esc = value => String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const dNow = () => M.device(store, ui.selected) || store.devices[0];
  const uNow = () => M.user(store, ui.user) || store.users[0];
  const cFor = d => M.contract(store, d.id);
  const rFor = d => { const j = M.join(store,d.id,ui.user); return j ? j.rights : {view:false,control:false,frequency:false,reset:false}; };
  const rightsText = r => M.fields.filter(k => r[k]).map(k => names[k]).join('、') || '无访问权限';
  const dateText = value => String(value || '').replace('T',' ');
  function restore(snapshot) {
    const p = snapshot && snapshot.privateContent;
    if (p && p.schema === 'rental-flow-v3' && p.store && p.store.version === 3) {
      if (Array.isArray(p.store.devices) && Array.isArray(p.store.joins) && Array.isArray(p.store.contracts) && Array.isArray(p.store.users) && Array.isArray(p.store.logs)) store = M.copy(p.store);
      if (p.ui) ui = Object.assign(ui,p.ui);
      if (!p.ui || !p.ui.incomeAvailable) { ui.mode='admin'; ui.page='income'; ui.incomeAvailable=true; }
      M.ensureAdministrator(store);
      if (!p.ui || !p.ui.mobileInventoryAvailable) { ui.mode='mini'; ui.user='admin'; ui.screen='devices'; ui.mobileInventoryAvailable=true; }
      if (!p.ui || !p.ui.reportsAvailable) { ui.mode='admin'; ui.page='reports'; ui.reportsAvailable=true; }
      if (!p.ui || !p.ui.userBackupAvailable) { ui.mode='admin'; ui.page='backup'; ui.userBackupAvailable=true; }
      if (!M.user(store,ui.user)) ui.user = 'chen';
      if (!M.device(store,ui.selected)) ui.selected = '05';
      if (!['mini','admin'].includes(ui.mode)) ui.mode = 'mini';
      if (!pages[ui.page]) ui.page = 'devices';
      if (!['devices','detail','scan','history','rental','profile','messages','sms','inventory'].includes(ui.screen)) ui.screen = 'devices';
    }
  }
  function save() {
    const snapshot = { schema:'rental-flow-v3', writer:stateWriter, revision:++stateRevision, store:M.copy(store), ui:M.copy(ui) };
    const payload = {modelContent:{preview:'租赁流程联动原型',mode:ui.mode==='mini'?'用户小程序':'管理后台',user:uNow().name,screen:ui.mode==='mini'?ui.screen:pages[ui.page],device:dNow().name,deviceCount:store.devices.length,contractCount:store.contracts.length,lastAction:store.logs[0]&&store.logs[0].action},privateContent:snapshot};
    const bytes = () => new TextEncoder().encode(JSON.stringify(payload)).length;
    while (bytes() > 16000 && snapshot.store.logs.length > 0) snapshot.store.logs.pop();
    if (bytes() <= 16000 && window.openai && window.openai.setWidgetState) window.openai.setWidgetState(payload).catch(function(){});
  }
  restore(window.openai && window.openai.widgetState);
  M.ensureReceipts(store);
  window.addEventListener('openai:set_globals',function(e){if(e.detail&&e.detail.globals&&e.detail.globals.widgetState){const state=e.detail.globals.widgetState,p=state.privateContent;if(p&&p.writer===stateWriter&&p.revision<=stateRevision)return;restore(state);permissionDraft=null;permissionDevice=null;render();}});
  function icons(){if(globalThis.lucide)globalThis.lucide.createIcons({attrs:{width:18,height:18}});}
  function toast(text){const el=ui.mode==='mini'?mini.querySelector('#im-toast'):admin.querySelector('#ia-toast');mini.querySelector('#im-toast').hidden=true;admin.querySelector('#ia-toast').hidden=true;el.textContent=text;el.hidden=false;root.querySelector('#wf-live').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.hidden=true;},3300);}
  function closeModal(){mLayer.hidden=true;aLayer.hidden=true;mLayer.innerHTML='';aLayer.innerHTML='';admin.style.minHeight='';mini.style.minHeight='';pendingLeave=null;}
  function fitModal(){requestAnimationFrame(()=>{[[admin,aLayer],[mini,mLayer]].forEach(([host,layer])=>{if(!layer.hidden){const dialog=layer.firstElementChild;if(dialog){const needed=dialog.offsetHeight+parseFloat(getComputedStyle(layer).paddingTop)+28;if(needed>host.offsetHeight)host.style.minHeight=needed+'px';}}});});}
  function modal(mode,title,subtitle,body){closeModal();const isMini=mode==='mini',layer=isMini?mLayer:aLayer;layer.innerHTML='<section class="'+(isMini?'im-sheet':'ia-modal')+'" role="dialog" aria-modal="true" aria-label="'+esc(title)+'"><div class="'+(isMini?'im-sheet-heading':'ia-modal-heading')+'"><h2>'+esc(title)+'</h2><button type="button" data-action="close" aria-label="关闭">'+icon('x')+'</button></div>'+(subtitle?'<p class="'+(isMini?'im-hint':'ia-modal-subtitle')+'">'+esc(subtitle)+'</p>':'')+body+'</section>';layer.hidden=false;icons();fitModal();const focus=layer.querySelector('input,select,button[data-action]:not([data-action="close"])');if(focus)focus.focus();}
  function row(label,value){return '<div class="wf-review-row"><span>'+esc(label)+'</span><span>'+esc(value)+'</span></div>';}
  function mRows(rows){return '<div class="im-info-list">'+rows.map(r=>'<div class="im-info-row"><span>'+esc(r[0])+'</span><span>'+esc(r[1])+'</span></div>').join('')+'</div>';}
  function aFooter(back,next,label){return '<div class="ia-modal-footer"><button type="button" class="ia-secondary" data-action="'+back+'">'+(back==='close'?'取消':'上一步')+'</button><button type="button" class="ia-primary" data-action="'+next+'">'+label+'</button></div>';}
  function errorBox(){return '<p id="wf-error" class="ia-error" role="alert"></p>';}
  function showError(error){const box=root.querySelector('#wf-error');if(box){box.textContent=error.message||String(error);fitModal();}else toast(error.message||String(error));}
  function clearFormError(e){if(e.target.matches('input,select,textarea')){const dialog=e.target.closest('[role="dialog"]');const box=dialog&&dialog.querySelector('#wf-error');if(box)box.textContent='';}}
  root.addEventListener('input',clearFormError);
  root.addEventListener('change',clearFormError);
  function dirtyPermissions(){if(ui.page!=='permissions'||!permissionDraft||permissionDevice!==ui.selected)return false;try{return M.permissionChanges(store,ui.selected,permissionDraft).length>0;}catch(e){return false;}}
  function leave(action){if(dirtyPermissions()){modal('admin','离开授权编辑？','当前权限修改还没有保存。','<p class="ia-note">离开将放弃这次修改，已生效的权限保持不变。</p><div class="ia-modal-footer"><button type="button" class="ia-secondary" data-action="close">继续编辑</button><button type="button" class="ia-primary" data-action="discard-leave">放弃修改并离开</button></div>');pendingLeave=action;}else action();}
  function navigate(mode,page,id){closeModal();if(id)ui.selected=id;ui.mode=mode;if(mode==='mini')ui.screen=page;else ui.page=page;permissionDraft=null;permissionDevice=null;render();save();}
  function progress(){const d=dNow(),c=cFor(d),j=M.join(store,d.id,ui.user);const checks=[true,Boolean(c),Boolean(j),Boolean(j&&M.fields.slice(1).some(k=>j.rights[k]))];root.querySelector('#wf-progress').innerHTML='<span class="wf-focus">当前演示：'+esc(d.name)+'</span><div class="wf-steps">'+['设备入库','合同登记','用户扫码','管理员授权'].map((s,i)=>'<span class="'+(checks[i]?'done':'')+'"><b>'+(checks[i]?'✓':i+1)+'</b>'+s+'</span>').join('')+'</div>';}
  function render(){root.querySelector('#wf-mini-section').hidden=ui.mode!=='mini';root.querySelector('#wf-admin-section').hidden=ui.mode!=='admin';root.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===ui.mode));root.querySelector('#wf-user-label').hidden=ui.mode!=='mini';root.querySelector('#wf-demo-user').innerHTML=store.users.map(u=>'<option value="'+u.id+'" '+(u.id===ui.user?'selected':'')+'>'+u.name+' · '+M.mask(u.phone)+'</option>').join('');progress();if(ui.mode==='mini')renderMini();else renderAdmin();icons();}
  function miniBanner(d){const c=cFor(d),rights=rFor(d),status=M.leaseStatus(store,d.id);if(status==='expired')return '<div class="im-banner red">'+icon('circle-alert')+'<div>租赁已到期'+(d.online&&!d.run?' · 停机已确认':' · 停机待确认')+'<p>续租后可恢复已授予的控制权限。</p></div></div>';if(!d.online)return '<div class="im-banner">'+icon('wifi-off')+'<div>设备离线，状态待更新<p>最后连接：今天 13:18，控制暂不可用。</p></div></div>';if(!rights.control&&!rights.frequency&&!rights.reset)return '<div class="im-banner blue">'+icon('lock-keyhole')+'<div>当前权限：仅查看<p>控制权限需要管理员单独授予。</p></div></div>';if(!c||status==='future')return '<div class="im-banner">'+icon('file-clock')+'<div>租赁合同尚未生效<p>当前仅可查看，控制需有有效租期。</p></div></div>';if(status==='near')return '<button type="button" class="im-banner" style="width:100%" data-action="rental">'+icon('calendar-clock')+'<div>租期剩余 '+M.days(c)+' 天<p>'+dateText(c.end)+' 到期，未续租将自动停机。</p></div></button>';return '';}
  function visibleDevices(){return store.devices.filter(d=>{const j=M.join(store,d.id,ui.user);return j&&j.rights.view;});}
  function miniCard(d){const c=cFor(d),r=rFor(d),status=M.leaseStatus(store,d.id),control=M.fields.slice(1).some(k=>r[k]);return '<button type="button" class="im-device" data-device="'+d.id+'"><div class="im-device-head"><div class="im-machine">'+icon('cpu')+'</div><div class="im-device-name"><h3>'+esc(d.name)+'</h3><p>'+esc(d.model)+' · '+esc(d.module.slice(-6))+'</p></div><span class="im-state '+(d.online?'':'off')+'">'+(d.online?'在线':'离线')+'</span></div><div class="im-device-mid"><span class="im-reading">'+(d.online?d.hz.toFixed(1):'—')+'<small>Hz</small></span><div class="im-tags"><span class="im-tag '+(d.run?'green':'')+'">'+(!d.online?'状态待更新':d.run?'运行中':'已停机')+'</span><span class="im-tag '+(status==='expired'?'red':control?'blue':'')+'">'+(status==='expired'?'租赁到期':control?'已授权控制':'仅查看')+'</span></div></div><div class="im-lease-line '+(status==='expired'?'expired':status==='near'?'warn':'')+'"><span>'+(c?c.end.slice(0,10)+' 到期':'尚未登记租赁合同')+'</span><span>'+(status==='near'?'剩余 '+M.days(c)+' 天':c?(c.owner===ui.user?'第一所有人':'关联设备'):'待登记')+icon('chevron-right')+'</span></div></button>';}
  function drawMiniList(){const box=content.querySelector('.im-devices');if(!box)return;const ds=visibleDevices().filter(d=>{const r=rFor(d),has=M.fields.slice(1).some(k=>r[k]);return (!ui.query||(d.name+d.model+d.module).toLowerCase().includes(ui.query.toLowerCase()))&&(ui.filter==='all'||ui.filter==='control'&&has||ui.filter==='view'&&!has);});box.innerHTML=ds.length?ds.map(miniCard).join(''):'<div class="im-empty">'+icon('scan-line')+'<p>暂无设备，扫码后可添加查看</p><button type="button" class="im-primary" style="margin-top:18px" data-action="scan">扫一扫，添加设备</button></div>';icons();}
  function miniDevices(){const ds=visibleDevices();content.innerHTML='<div class="im-intro"><div><h1>我的设备</h1><p>'+uNow().name+' · '+M.mask(uNow().phone)+'</p></div><button type="button" class="im-scan wf-scan-entry" data-action="scan">'+icon('scan-line')+'扫一扫</button></div><div class="im-summary">'+[[ds.length,'关联设备'],[ds.filter(d=>d.online).length,'当前在线'],[ds.filter(d=>M.leaseStatus(store,d.id)==='near').length,'即将到期']].map(a=>'<div><strong>'+a[0]+'</strong><span>'+a[1]+'</span></div>').join('')+'</div><label class="im-search">'+icon('search')+'<input id="wf-mini-search" placeholder="搜索设备名称 / 编号" aria-label="搜索设备名称或编号" value="'+esc(ui.query)+'"></label><div class="im-filters">'+[['all','全部设备'],['control','已授权控制'],['view','仅查看']].map(x=>'<button type="button" data-mini-filter="'+x[0]+'" aria-pressed="'+(ui.filter===x[0])+'">'+x[1]+'</button>').join('')+'</div><div class="im-devices"></div>';drawMiniList();}
  function miniDetail(){const d=dNow();if(!M.can(store,d.id,ui.user,'view').ok){content.innerHTML='<h1>访问权限已收回</h1><p class="im-note">请联系管理员重新授权。扫码不会恢复已收回的权限。</p><button type="button" class="im-primary" data-action="mini-list">返回设备列表</button>';return;}const c=cFor(d),r=rFor(d);content.innerHTML='<div class="im-detail-head"><div><h2>'+esc(d.name)+'</h2><p>'+esc(d.model)+' · 第一所有人：'+(c?M.user(store,c.owner).name:'待登记')+'</p></div><span class="im-state '+(d.online?'':'off')+'">'+(d.online?'在线':'离线')+'</span></div>'+miniBanner(d)+'<section class="im-frequency"><div class="im-frequency-label"><span>实际运行频率</span><span class="im-tag '+(d.run?'green':'')+'">'+(!d.online?'待更新':d.run?'运行中':'已停机')+'</span></div><div class="im-big-number">'+(d.online?d.hz.toFixed(1):'—')+'<span>Hz</span></div><div class="im-meter"><i style="width:'+(d.online?d.hz/80*100:0)+'%"></i></div><div class="im-set-frequency"><span>设定频率 <strong>'+d.target.toFixed(1)+' Hz</strong></span><button type="button" data-action="frequency" '+(M.can(store,d.id,ui.user,'frequency').ok?'':'disabled')+'>'+icon('sliders-horizontal')+'调整</button></div></section><div class="im-metrics">'+[['输出电流',d.current.toFixed(1),'A'],['输出电压',d.voltage,'V'],['母线电压',d.bus,'V']].map(v=>'<div><p>'+v[0]+'</p><strong>'+(d.online?v[1]:'—')+'</strong><small>'+v[2]+'</small></div>').join('')+'</div><div class="im-section-line"><h3>设备控制</h3><span>逐项授权</span></div><div class="im-command-grid">'+[['start','启动','play'],['stop','停止','square'],['reset','故障复位','rotate-ccw']].map(a=>'<button type="button" class="'+a[0]+'" data-command="'+a[0]+'" '+(M.can(store,d.id,ui.user,a[0]).ok&&(a[0]!=='start'||!d.run)&&(a[0]!=='stop'||d.run)?'':'disabled')+'>'+icon(a[2])+a[1]+'</button>').join('')+'</div><p class="im-updated">'+(d.online?'示例数据更新于 14:32:08':'离线数据不代表设备当前状态')+'</p><div class="wf-rights">'+M.fields.map(k=>'<span class="im-tag '+(r[k]?'blue':'')+'">'+names[k]+' '+(r[k]?'✓':'未授权')+'</span>').join('')+'</div><div class="im-links" style="margin-top:18px"><button type="button" class="im-link" data-action="history"><span>'+icon('chart-no-axes-combined')+'历史运行数据</span>'+icon('chevron-right')+'</button><button type="button" class="im-link" data-action="rental"><span>'+icon('file-text')+'租赁与权限信息</span>'+icon('chevron-right')+'</button></div>';}
  function scanOptions(){const options=store.devices.map(d=>[M.qr(d),d.name]).concat([['HN|VF-22|NOT_IN_STOCK','未入库二维码'],['INVALID','无效二维码'],['OTHER|VF-99|DEMO4G001001','档案不一致']]);if(!options.some(x=>x[0]===ui.scanRaw))options.unshift([ui.scanRaw,'自定义识别内容']);return options.map(x=>'<option value="'+esc(x[0])+'" '+(ui.scanRaw===x[0]?'selected':'')+'>'+esc(x[1])+'</option>').join('');}
  function miniScan(){if(scanResult){const d=scanResult.device,c=cFor(d);content.innerHTML='<div class="wf-success-icon">'+icon(scanAdded?'check':'scan-line')+'</div><div class="wf-centered"><h2>'+(scanAdded?'设备已添加':scanResult.added?'此设备已在列表中':'已识别设备')+'</h2><p class="im-note">'+esc(d.name)+'</p></div>'+mRows([['厂商代号',d.vendor],['变频器型号',d.model],['4G 模块 ID',d.module],['第一所有人',c?M.user(store,c.owner).name:'尚未登记合同'],['添加后的权限',scanResult.added?rightsText(scanResult.rights):'仅查看']])+'<div class="im-banner blue">'+icon('shield-check')+'<div>扫码不会改变第一所有人<p>启停、调频和复位需要管理员授权。</p></div></div><button type="button" class="im-primary" data-action="'+(scanAdded||scanResult.added?'scan-open':'scan-confirm')+'">'+(scanAdded||scanResult.added?'查看设备':'确认添加 · 仅查看')+'</button><button type="button" class="im-secondary" style="margin-top:10px" data-action="scan-again">继续扫码</button>';return;}content.innerHTML='<h1>扫一扫</h1><p class="im-note">扫描设备二维码，添加后默认仅查看</p><div class="wf-scanner"><div class="wf-viewfinder">'+icon('scan-line')+'</div><span>将设备二维码放入框内</span><p>原型扫码演示 · 不调用真实相机</p></div><label class="wf-field">选择演示二维码<select class="wf-select" id="wf-scan-select" aria-label="选择演示二维码">'+scanOptions()+'</select></label><label class="wf-field">二维码识别内容<input id="wf-scan-raw" value="'+esc(ui.scanRaw)+'" aria-label="二维码识别内容"></label>'+(scanError?'<div class="im-banner red" role="alert">'+icon('circle-alert')+'<div>'+esc(scanError)+'</div></div>':'')+'<button type="button" class="im-primary" data-action="scan-identify">'+icon('scan-line')+'演示相机扫码</button><div class="wf-two-actions"><button type="button" class="im-secondary" data-action="scan-album">'+icon('image')+'相册识别演示</button><button type="button" class="im-secondary" data-action="scan-cancel">取消扫码</button></div>';}
  function miniRental(){const d=dNow(),c=cFor(d);if(!M.can(store,d.id,ui.user,'view').ok){miniDetail();return;}content.innerHTML='<h1>租赁与权限</h1><p class="im-note">'+esc(d.name)+'</p>'+mRows([['第一所有人',c?M.user(store,c.owner).name:'待登记'],['合同编号',c?c.number:'待登记'],['绑定手机号',c?M.mask(M.user(store,c.owner).phone):'待登记'],['租赁方式','按月租赁'],['租期开始',c?dateText(c.start):'待登记'],['租期结束',c?dateText(c.end):'待登记'],['我的权限',rightsText(rFor(d))]])+'<h3 style="margin-top:20px">设备档案</h3>'+mRows([['厂商 / 型号',d.vendor+' / '+d.model],['4G 模块 ID',d.module],['位置',d.place||'未填写']])+'<p class="im-note">租期及第一所有人以管理员登记为准。控制权限需要单独授权。</p>';}
  function miniHistory(){if(!M.can(store,ui.selected,ui.user,'view').ok){miniDetail();return;}const current=ui.metric==='current';content.innerHTML='<h1>历史数据</h1><p class="im-note">'+esc(dNow().name)+' · 2026-10-21</p><div class="im-history-controls"><div class="im-segment">'+[['frequency','频率'],['current','电流']].map(x=>'<button type="button" data-metric="'+x[0]+'" aria-pressed="'+(ui.metric===x[0])+'">'+x[1]+'</button>').join('')+'</div><div class="im-segment">'+[['chart','曲线'],['table','表格']].map(x=>'<button type="button" data-history="'+x[0]+'" aria-pressed="'+(ui.historyView===x[0])+'">'+x[1]+'</button>').join('')+'</div></div><div class="im-chart-panel"><div class="im-chart-title"><span>'+(current?'输出电流 / A':'实际频率 / Hz')+'</span><span>示例记录</span></div>'+(ui.historyView==='table'?'<table class="im-data-table"><thead><tr><th>时间</th><th>'+(current?'电流 / A':'频率 / Hz')+'</th></tr></thead><tbody>'+['00:00','06:00','08:00','10:00','12:00','14:30'].map((t,i)=>'<tr><td>'+t+'</td><td>'+([2,3].includes(i)?'0.0':current?'6.7':'42.0')+'</td></tr>').join('')+'</tbody></table>':'<svg class="im-chart" viewBox="0 0 320 210" role="img" aria-label="示例历史曲线，八点至十点停机"><path class="im-gridline" d="M35 20H302M35 60H302M35 100H302M35 140H302M35 180H302"/><text x="7" y="24">'+(current?'8':'50')+'</text><text x="7" y="104">'+(current?'4':'25')+'</text><text x="15" y="184">0</text><text x="35" y="205">00:00</text><text x="116" y="205">06:00</text><text x="198" y="205">12:00</text><text x="270" y="205">18:00</text><path class="im-curve" d="M35 48L90 47L140 48L141 180L181 180L182 48L242 47L302 46"/></svg>')+'</div>';}
  function miniMessages(){const events=store.logs.filter(l=>M.can(store,l.device,ui.user,'view').ok);content.innerHTML='<h1>消息</h1><p class="im-note">租赁与授权动态</p>'+events.slice(0,8).map(l=>'<article class="im-message"><div class="im-message-head"><span>'+icon('bell')+'</span><h3>'+esc(l.action)+'</h3><small>示例记录</small></div><p>'+esc(M.device(store,l.device).name)+'<br>'+esc(l.result)+'</p><button type="button" data-device="'+l.device+'">查看设备'+icon('chevron-right')+'</button></article>').join('')+(events.length?'':'<p class="im-empty">暂无消息</p>');}
  function miniProfile(){const u=uNow(),owned=store.contracts.filter(c=>c.owner===u.id);content.innerHTML='<div class="im-person"><div class="im-avatar">'+u.name[0]+'</div><div><h2>'+u.name+'</h2><p>'+M.mask(u.phone)+' · 微信绑定手机号</p></div></div><div class="im-rental-overview"><p>我的承租设备</p><div class="im-overview-row"><div><strong>'+owned.length+'</strong><span>台</span></div><span class="im-small">以合同登记为准</span></div></div><div class="im-links"><button type="button" class="im-link" data-action="scan"><span>'+icon('scan-line')+'扫码添加设备</span>'+icon('chevron-right')+'</button><button type="button" class="im-link" data-action="sms"><span>'+icon('message-square')+'短信提醒服务</span><small>暂未开放</small>'+icon('chevron-right')+'</button></div><p class="im-note">扫码仅建立查看关联，第一所有人由管理员按合同登记。</p>';}
  function miniSms(){content.innerHTML='<h1>短信提醒</h1><p class="im-note">到期前 7 天、3 天、1 天提醒</p><div class="im-rental-overview"><p>短信服务余额</p><div class="im-overview-row"><div><strong>—</strong></div><span>服务待开通</span></div></div>'+mRows([['计费方式','充值余额，按条扣费'],['接收手机号',M.mask(uNow().phone)],['短信单价','待确定'],['充值状态','暂未开放']])+'<button type="button" class="im-primary" disabled>充值暂未开放</button><p class="im-note">短信费用与设备租金分别管理。当前仅预留接口，不提供充值或发信。</p>';}
  function renderMini(){const sub=!['devices','messages','profile'].includes(ui.screen);mini.querySelector('#im-back').hidden=!sub;mini.querySelector('#im-back').setAttribute('aria-label','返回');mini.querySelector('#im-bottom').hidden=sub;mini.querySelector('#im-navtitle').textContent=({detail:'设备详情',scan:'扫码添加',rental:'租赁信息',history:'历史数据',sms:'短信服务'})[ui.screen]||'云控租赁';mini.querySelector('#im-bottom').innerHTML=[['devices','设备','panels-top-left'],['scan','扫一扫','scan-line'],['messages','消息','bell'],['profile','我的','user-round']].map(v=>'<button type="button" data-mini-nav="'+v[0]+'" class="'+(ui.screen===v[0]?'active':'')+'">'+icon(v[2])+'<span>'+v[1]+'</span></button>').join('');({devices:miniDevices,detail:miniDetail,scan:miniScan,rental:miniRental,history:miniHistory,messages:miniMessages,profile:miniProfile,sms:miniSms}[ui.screen]||miniDevices)();}
  function aHeading(title,subtitle,action,label,ic){return '<div class="ia-heading"><div><h1>'+title+'</h1><p>'+subtitle+'</p></div>'+(action?'<button type="button" class="ia-primary" data-action="'+action+'">'+icon(ic||'plus')+label+'</button>':'')+'</div>';}
  function badge(d){const s=M.leaseStatus(store,d.id);return '<span class="ia-status '+({active:'green',near:'amber',expired:'red',future:'blue',stock:''})[s]+'">'+({active:'租赁中',near:'即将到期',expired:'已到期',future:'待起租',stock:'待出租'})[s]+'</span>';}
  function ownerCell(d){const c=cFor(d),u=c&&M.user(store,c.owner);return u?esc(u.name)+'<small>'+M.mask(u.phone)+'</small>':'<span style="color:var(--ia-muted)">未登记</span>';}
  function filteredAdmin(){return store.devices.filter(d=>{const c=cFor(d),s=M.leaseStatus(store,d.id);return (!ui.adminQuery||(d.name+d.module+d.model+(c?M.user(store,c.owner).phone:'')).toLowerCase().includes(ui.adminQuery.toLowerCase()))&&(ui.adminFilter==='all'||ui.adminFilter==='stock'&&!c||ui.adminFilter==='rented'&&c&&s!=='expired'||ui.adminFilter==='expired'&&s==='expired');});}
  function drawAdminRows(){const ds=filteredAdmin();main.querySelector('#wf-device-rows').innerHTML=ds.length?ds.map(d=>{const c=cFor(d);return '<tr><td><div class="ia-device-name">'+esc(d.name)+'</div><small>'+esc(d.model)+' · '+esc(d.module.slice(-6))+'</small></td><td>'+ownerCell(d)+'</td><td>'+badge(d)+'<small><i class="ia-dot '+(d.online?'':'off')+'"></i>'+(d.online?(d.run?'在线 · 运行中':'在线 · 已停机'):'离线 · 待更新')+'</small></td><td>'+ (c?c.end.slice(0,10)+'<small>'+c.end.slice(11)+' 到期</small>':'待登记租期')+'</td><td><div class="ia-table-actions"><button type="button" class="ia-text-button" data-lease-device="'+d.id+'">'+(c?'合同':'登记合同')+'</button><button type="button" class="ia-text-button" data-authorize="'+d.id+'">授权</button><button type="button" class="ia-text-button" data-info="'+d.id+'">详情</button></div></td></tr>';}).join(''):'<tr><td colspan="5" class="ia-empty">没有找到相关设备</td></tr>';main.querySelector('#wf-device-count').textContent='共 '+ds.length+' 台设备';}
  function adminDevices(){const counts=[store.devices.length,store.devices.filter(d=>['active','near','future'].includes(M.leaseStatus(store,d.id))).length,store.devices.filter(d=>M.leaseStatus(store,d.id)==='near').length,store.devices.filter(d=>M.leaseStatus(store,d.id)==='expired').length];main.innerHTML=aHeading('设备管理','扫码入库、登记租赁，再按用户授予权限','inventory','扫码入库','scan-line')+'<div class="ia-stats">'+[['全部设备','boxes'],['已登记租赁','file-text'],['7 天内到期','calendar-clock'],['租赁已到期','circle-alert']].map((v,i)=>'<div class="ia-stat"><div class="ia-stat-label">'+v[0]+icon(v[1])+'</div><strong>'+counts[i]+'</strong><small>'+['设备档案','合同与付款已登记','跟进续租','查看停机结果'][i]+'</small></div>').join('')+'</div><section class="ia-panel"><div class="ia-toolbar"><div class="ia-tabs">'+[['all','全部设备'],['rented','租赁中'],['stock','待出租'],['expired','已到期']].map(v=>'<button type="button" data-admin-filter="'+v[0]+'" aria-pressed="'+(ui.adminFilter===v[0])+'">'+v[1]+'</button>').join('')+'</div><label class="ia-search">'+icon('search')+'<input id="wf-admin-search" placeholder="设备名称 / 模块 ID / 手机号" aria-label="搜索设备或手机号" value="'+esc(ui.adminQuery)+'"></label></div><div class="ia-table-wrap"><table class="ia-table"><thead><tr><th>设备名称 / 型号</th><th>第一所有人</th><th>租赁 / 运行状态</th><th>租赁到期时间</th><th>操作</th></tr></thead><tbody id="wf-device-rows"></tbody></table></div><div class="ia-table-foot"><span id="wf-device-count"></span><span>已显示全部结果</span></div></section><p class="ia-note">用户扫码后默认仅查看；合同登记不自动开通控制权限。设备、合同及授权在两个演示视角中实时联动。</p>';drawAdminRows();}
  function adminLeases(){main.innerHTML=aHeading('租赁合同','合同签约人作为第一所有人，付款与租期单独登记','new-contract','登记合同','file-plus-2')+'<section class="ia-panel"><div class="ia-table-wrap"><table class="ia-table"><thead><tr><th>合同 / 设备</th><th>第一所有人</th><th>月租 / 首次实收</th><th>租期至</th><th>操作</th></tr></thead><tbody>'+store.contracts.map(c=>{const d=M.device(store,c.device);return '<tr><td>'+esc(c.number)+'<small>'+esc(d.name)+'</small></td><td>'+ownerCell(d)+'</td><td>¥ '+c.rent.toFixed(2)+'<small>首次实收 ¥ '+c.paid.toFixed(2)+'</small></td><td>'+c.end.slice(0,10)+'<small>'+c.end.slice(11)+' '+(M.leaseStatus(store,d.id)==='expired'?'已到期':'')+'</small></td><td><div class="ia-table-actions"><button type="button" class="ia-text-button" data-contract-details="'+d.id+'">详情</button><button type="button" class="ia-text-button" data-renew="'+d.id+'">续租</button></div></td></tr>';}).join('')+'</tbody></table></div></section><p class="ia-note">时间均为北京时间。示例合同金额不代表实际报价；登记只改变租赁归属，不改变用户操作权限。</p>';}
  function adminPermissions(){const d=dNow(),c=cFor(d),joins=store.joins.filter(j=>j.device===d.id);if(!permissionDraft||permissionDevice!==d.id){permissionDevice=d.id;permissionDraft={};joins.forEach(j=>{permissionDraft[j.user]=M.copy(j.rights);});}main.innerHTML=aHeading('用户授权','同一设备可关联多人，每位用户的权限分别生效')+'<section class="ia-panel"><div class="ia-permission-summary"><div><h3>'+esc(d.name)+'</h3><p>第一所有人：'+(c?M.user(store,c.owner).name+' · '+M.mask(M.user(store,c.owner).phone):'待合同登记')+'</p></div><select id="wf-perm-device" class="ia-select" aria-label="选择授权设备">'+store.devices.map(x=>'<option value="'+x.id+'" '+(d.id===x.id?'selected':'')+'>'+esc(x.name)+'</option>').join('')+'</select></div><div class="ia-table-wrap"><table class="ia-table ia-perm-table"><thead><tr><th>已扫码关联的用户</th><th>查看</th><th>启动 / 停止</th><th>修改频率</th><th>故障复位</th></tr></thead><tbody>'+(joins.length?joins.map(j=>{const u=M.user(store,j.user),r=permissionDraft[u.id];return '<tr><td>'+esc(u.name)+' <span class="ia-status '+(c&&c.owner===u.id?'blue':'')+'">'+(c&&c.owner===u.id?'第一所有人':'关联用户')+'</span><small>'+M.mask(u.phone)+'</small></td>'+M.fields.map(k=>'<td><label class="ia-perm-check"><input type="checkbox" data-perm="'+k+'" data-perm-user="'+u.id+'" aria-label="'+u.name+' '+names[k]+'" '+(r[k]?'checked':'')+'></label></td>').join('')+'</tr>';}).join(''):'<tr><td class="ia-empty" colspan="5">还没有用户扫码添加此设备。</td></tr>')+'</tbody></table></div><div class="ia-permission-footer"><span id="wf-permission-hint">扫码默认仅查看，控制权限需要单独授予。</span><button type="button" class="ia-primary" data-action="review-permissions" disabled>'+icon('check')+'保存授权</button></div></section>'+(c&&!M.join(store,d.id,c.owner)?'<div class="ia-information">'+icon('scan-line')+'<span>合同签约人 '+M.user(store,c.owner).name+' 尚未扫码添加，请先完成扫码关联。</span></div>':'')+'<p class="ia-note">收回查看权限会同时关闭该用户的控制权限。再次扫码不会自动恢复已收回的权限，第一所有人不会随授权变更。</p>';updatePermissionButton();}
  function updatePermissionButton(){const b=main.querySelector('[data-action="review-permissions"]');if(!b)return;const changes=M.permissionChanges(store,ui.selected,permissionDraft);b.disabled=changes.length===0;main.querySelector('#wf-permission-hint').textContent=changes.length?'有 '+changes.length+' 位用户的权限待保存':'当前权限已保存';}
  function adminReminders(){const ds=store.devices.filter(d=>['near','expired'].includes(M.leaseStatus(store,d.id)));main.innerHTML=aHeading('到期与提醒','提前 7 / 3 / 1 天提醒，到期未续租自动停机')+'<section class="ia-panel">'+ds.map(d=>{const c=cFor(d),expired=M.leaseStatus(store,d.id)==='expired';return '<article class="ia-rental-item"><div><h3>'+esc(d.name)+' '+badge(d)+'</h3><p>第一所有人：'+M.user(store,c.owner).name+' · '+M.mask(M.user(store,c.owner).phone)+'</p><p>到期时间：'+dateText(c.end)+'</p>'+(expired?'<span class="ia-status '+(d.online&&!d.run?'green':'amber')+'">'+(d.online&&!d.run?'设备停机已确认':'停机结果待确认')+'</span>':'<div class="ia-timeline">'+[7,3,1].map(n=>'<span>'+new Date(M.epoch(c.end)-n*86400000+8*3600000).toISOString().slice(5,10)+' · 提前 '+n+' 天</span>').join('<i></i>')+'</div>')+'</div><button type="button" class="ia-secondary" style="align-self:start" data-renew="'+d.id+'">登记续租</button></article>';}).join('')+'</section><section class="ia-panel" style="margin-top:22px"><div class="ia-toolbar"><h3>短信服务</h3><span class="ia-status">仅预留接口</span></div><div style="padding:18px"><p class="ia-note" style="margin:0">充值余额、按条扣费。余额查询、充值及消费记录接口预留，当前不发信、不扣费、不充值。</p><button type="button" class="ia-secondary" style="margin-top:14px" disabled>充值渠道待确定</button></div></section>';}
  function adminLogs(){main.innerHTML=aHeading('操作记录','追溯入库、扫码、合同、授权及控制结果')+'<section class="ia-panel"><div class="ia-table-wrap"><table class="ia-table"><thead><tr><th>时间 / 操作人</th><th>操作</th><th>设备</th><th>结果</th></tr></thead><tbody>'+store.logs.map(l=>'<tr><td>10-21 14:32<small>'+esc(l.who)+'</small></td><td>'+esc(l.action)+'</td><td>'+esc((M.device(store,l.device)||{}).name)+'</td><td style="max-width:280px">'+esc(l.result)+'</td></tr>').join('')+'</tbody></table></div></section>';}
  function renderAdmin(){admin.style.setProperty('--ia-row-space',ui.density+'px');admin.querySelector('#ia-breadcrumb').textContent=pages[ui.page];admin.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===ui.page));({devices:adminDevices,leases:adminLeases,permissions:adminPermissions,reminders:adminReminders,logs:adminLogs}[ui.page]||adminDevices)();}
  function startInventory(){inventoryDraft={raw:'HN|VF-22|DEMO4G001'+String(store.next).padStart(3,'0'),name:'',place:'海口仓库'};inventoryStep(1);}
  function inventoryStep(step){const labels=['识别二维码','确认设备档案','入库完成'];let body='<div class="wf-steps">'+labels.map((x,i)=>'<span class="'+(i===step-1?'active':'')+'">'+(i+1)+'. '+x+'</span>').join('')+'</div>';if(step===1){body+='<label class="ia-field">二维码内容（原型示例）<input id="wf-inventory-qr" value="'+esc(inventoryDraft.raw)+'" autocomplete="off"></label><p class="ia-note">厂商代号 + 变频器型号 + 4G 模块 ID。演示使用 | 分隔。</p>'+errorBox()+aFooter('close','inventory-parse','演示扫码并解析');}if(step===2){body+='<div class="wf-review">'+row('厂商代号',inventoryDraft.parsed.vendor)+row('变频器型号',inventoryDraft.parsed.model)+row('4G 模块 ID',inventoryDraft.parsed.module)+'</div><label class="ia-field">设备名称 *<input id="wf-inventory-name" maxlength="30" value="'+esc(inventoryDraft.name||'新入库 '+String(store.next).padStart(2,'0')+' 号变频器')+'"></label><label class="ia-field">存放位置<input id="wf-inventory-place" maxlength="60" value="'+esc(inventoryDraft.place)+'"></label>'+errorBox()+aFooter('inventory-back','inventory-save','确认入库');}if(step===3){const d=dNow();body+='<div class="wf-success"><span>'+icon('check')+'</span><h2>设备已入库</h2><p>'+esc(d.name)+' · 待出租</p></div><div class="wf-review">'+row('设备编号','INV-'+d.id)+row('4G 模块 ID',d.module)+'</div><p class="ia-note">尚未登记第一所有人，也未向任何用户授予权限。</p><div class="wf-footer-buttons"><button type="button" class="ia-secondary" data-action="close">返回设备列表</button><button type="button" class="ia-primary" data-contract-start="'+d.id+'">下一步：登记合同</button></div>';}modal('admin','设备扫码入库','识别与登记均为原型演示。',body);}
  function startContract(id){const ds=store.devices.filter(d=>!cFor(d));if(!ds.length){toast('当前没有待出租设备，请先扫码入库。');return;}contractDraft={device:ds.some(d=>d.id===id)?id:ds[0].id,phone:'',number:'ZL-2026-'+String(1000+store.contracts.length+1),rent:'',paid:'',paidAt:M.NOW.slice(0,10),reference:'',start:'2026-10-21T00:00',end:'2026-11-21T18:00'};contractStep(1);}
  function readContract(){['device','phone','number','rent','paid','paidAt','reference','start','end'].forEach(k=>{const e=root.querySelector('#wf-contract-'+k);if(e)contractDraft[k]=e.value;});}
  function contractStep(step){let body='<div class="wf-steps">'+['填写合同','核对登记','完成'].map((s,i)=>'<span class="'+(step===i+1?'active':'')+'">'+(i+1)+'. '+s+'</span>').join('')+'</div>';if(step===1){body+='<label class="ia-field">出租设备 *<select id="wf-contract-device">'+store.devices.filter(d=>!cFor(d)).map(d=>'<option value="'+d.id+'" '+(contractDraft.device===d.id?'selected':'')+'>'+esc(d.name)+'</option>').join('')+'</select></label><div class="wf-lookup"><label class="ia-field">合同签约人的微信绑定手机号 *<input id="wf-contract-phone" inputmode="tel" list="wf-customer-list" value="'+esc(contractDraft.phone)+'" placeholder="输入或选择已登记手机号"></label><button type="button" class="ia-secondary" data-action="lookup-owner">查询用户</button></div><datalist id="wf-customer-list">'+store.users.map(u=>'<option value="'+u.phone+'">'+u.name+'（示例）</option>').join('')+'</datalist><div id="wf-owner-result" class="ia-note" style="margin:0">可体验：陈先生 13800002608 / 王师傅 13600001820</div><div class="wf-field-group"><label class="ia-field">合同编号 *<input id="wf-contract-number" value="'+esc(contractDraft.number)+'"></label><label class="ia-field">月租金额 / 元 *<input id="wf-contract-rent" type="number" min="0.01" step="0.01" value="'+esc(contractDraft.rent)+'"></label><label class="ia-field">起租时间（北京时间）*<input id="wf-contract-start" type="datetime-local" value="'+esc(contractDraft.start)+'"></label><label class="ia-field">到期时间（北京时间）*<input id="wf-contract-end" type="datetime-local" value="'+esc(contractDraft.end)+'"></label><label class="ia-field">本期实收金额 / 元 *<input id="wf-contract-paid" type="number" min="0.01" step="0.01" value="'+esc(contractDraft.paid)+'"></label><label class="ia-field">实际收款日期 *<input id="wf-contract-paidAt" type="date" max="'+M.NOW.slice(0,10)+'" value="'+esc(contractDraft.paidAt)+'"></label><label class="ia-field">付款记录编号<input id="wf-contract-reference" value="'+esc(contractDraft.reference)+'" placeholder="选填"></label></div>'+errorBox()+aFooter('close','contract-review','下一步：核对');}if(step===2){const v=M.validateContract(store,contractDraft),u=M.user(store,v.owner);body+='<div class="wf-review">'+[['设备',M.device(store,v.device).name],['合同编号',v.number],['第一所有人',u.name+' · '+M.mask(u.phone)],['租期开始',dateText(v.start)],['租期结束',dateText(v.end)],['月租金额','¥ '+v.rent.toFixed(2)],['本期实收','¥ '+v.paid.toFixed(2)],['实际收款日期',v.paidAt],['付款记录',v.reference||'未填写']].map(r=>row(r[0],r[1])).join('')+'</div><div class="ia-information">'+icon('shield-check')+'<span>登记只确认租赁归属，不自动开通控制权限。用户扫码后默认仅查看。</span></div><label class="wf-check-line"><input id="wf-contract-confirmed" type="checkbox"><span>已核对合同签约人、租期及实际付款记录</span></label>'+errorBox()+aFooter('contract-back','contract-save','确认登记');}if(step===3){const d=dNow(),c=cFor(d),u=M.user(store,c.owner);body+='<div class="wf-success"><span>'+icon('check')+'</span><h2>合同登记完成</h2><p>'+esc(d.name)+' · 第一所有人 '+u.name+'</p></div><div class="wf-review">'+row('合同编号',c.number)+row('租期至',dateText(c.end))+row('控制权限','未自动开通')+'</div><div class="wf-footer-buttons"><button type="button" class="ia-secondary" data-authorize="'+d.id+'">查看授权名单</button><button type="button" class="ia-primary" data-owner-scan="'+d.id+'">体验所属人扫码添加</button></div>';}modal('admin','合同与付款登记','第一所有人以签约用户的微信绑定手机号为准。',body);}
  function contractDetails(id){const d=M.device(store,id),c=cFor(d),u=M.user(store,c.owner);modal('admin','合同详情',d.name,'<div class="wf-review">'+[['合同编号',c.number],['第一所有人',u.name+' · '+M.mask(u.phone)],['起租时间',dateText(c.start)],['到期时间',dateText(c.end)],['月租金额','¥ '+c.rent.toFixed(2)],['首次登记实收','¥ '+c.paid.toFixed(2)],['首次收款日期',c.paidAt||'未登记日期'],['付款记录',c.reference||'未填写']].map(r=>row(r[0],r[1])).join('')+'</div><div class="wf-footer-buttons"><button type="button" class="ia-secondary" data-authorize="'+id+'">管理授权</button><button type="button" class="ia-primary" data-renew="'+id+'">登记续租</button></div>');}
  function deviceInfo(id){const d=M.device(store,id);modal('admin','设备档案',d.name,'<div class="wf-review">'+[['设备编号','INV-'+d.id],['厂商 / 型号',d.vendor+' / '+d.model],['4G 模块 ID',d.module],['位置',d.place||'未填写'],['第一所有人',cFor(d)?M.user(store,cFor(d).owner).name:'待合同登记']].map(r=>row(r[0],r[1])).join('')+'</div><p class="wf-QR-line">'+esc(M.qr(d))+'</p><div class="wf-footer-buttons"><button type="button" class="ia-secondary" data-user-scan="'+id+'">在用户端演示扫码</button><button type="button" class="ia-primary" data-authorize="'+id+'">管理授权</button></div>');}
  function reviewPermissions(){const changes=M.permissionChanges(store,ui.selected,permissionDraft);if(!changes.length)return;modal('admin','确认权限变更',dNow().name+' · '+changes.length+' 位用户',changes.map(c=>'<div class="wf-delta"><strong>'+M.user(store,c.uid).name+' · '+M.mask(M.user(store,c.uid).phone)+'</strong><p>当前：'+rightsText(c.before)+'</p><p>变更后：'+rightsText(c.next)+'</p></div>').join('')+'<label class="ia-field">变更说明（选填）<textarea id="wf-permission-reason" maxlength="100" placeholder="例如：授权现场操作人员"></textarea></label>'+errorBox()+'<div class="ia-modal-footer"><button type="button" class="ia-secondary" data-action="close">返回编辑</button><button type="button" class="ia-primary" data-action="apply-permissions">确认生效</button></div>');}
  function renewal(id){renewDevice=id;const d=M.device(store,id),c=cFor(d);let end=c.end.slice(0,4)+'-11-'+c.end.slice(8);if(M.epoch(end)<=M.epoch(c.end))end='2026-12-21T18:00';modal('admin','登记续租',d.name+' · 第一所有人 '+M.user(store,c.owner).name,'<div class="wf-review">'+row('原到期时间',dateText(c.end))+'</div><label class="ia-field">新的到期时间（北京时间）<input id="wf-renew-end" type="datetime-local" value="'+end+'"></label><label class="ia-field">本次实收金额 / 元<input id="wf-renew-paid" type="number" min="0.01" step="0.01" value="'+c.rent+'"></label><label class="ia-field">实际收款日期<input id="wf-renew-paidAt" type="date" max="'+M.NOW.slice(0,10)+'" value="'+M.NOW.slice(0,10)+'"></label><label class="ia-field">付款记录编号<input id="wf-renew-reference" placeholder="选填"></label><label class="wf-check-line"><input id="wf-renew-confirmed" type="checkbox">已核对续租及付款记录</label><p class="ia-note">更新提醒和停机计划，保留已有授权，设备不会自动启动。</p>'+errorBox()+aFooter('close','renew-save','确认续租'));}
  function openFrequency(){const d=dNow();if(!M.can(store,d.id,ui.user,'frequency').ok)return;modal('mini','调整运行频率',d.name,'<label class="im-field">目标频率 / Hz<input id="wf-frequency" type="number" min="0" max="80" step="0.1" value="'+d.target+'"></label><p class="im-hint">示例允许范围 0–80 Hz</p><p id="wf-error" class="im-error" role="alert"></p><div class="im-sheet-footer"><button type="button" class="im-secondary" data-action="close">取消</button><button type="button" class="im-primary" data-action="frequency-save">确认调整</button></div>');}
  function openCommand(action){const d=dNow();if(!M.can(store,d.id,ui.user,action).ok)return;const label=({start:'启动',stop:'停止',reset:'故障复位'})[action];modal('mini','确认'+label,d.name,'<p class="im-hint">'+(action==='start'?'按设定频率 '+d.target.toFixed(1)+' Hz 启动。':action==='stop'?'停止当前设备运行。':'向设备下发故障复位指令。')+'</p><div class="im-sheet-footer"><button type="button" class="im-secondary" data-action="close">取消</button><button type="button" class="im-primary" data-confirm-command="'+action+'">确认'+label+'</button></div>');}
  function executeCommand(action,value,button){if(commandBusy)return;const did=ui.selected,uid=ui.user;commandBusy=true;if(button){button.disabled=true;button.textContent='等待设备反馈…';}setTimeout(()=>{commandBusy=false;try{M.command(store,did,uid,action,value);closeModal();render();save();toast('模拟设备已确认 · '+({start:'启动成功',stop:'已停机',frequency:'频率已更新',reset:'复位完成'})[action]);}catch(e){if(button&&button.isConnected){button.disabled=false;button.textContent='重新确认';}showError(e);}},450);}
  function startScan(id,uid){if(uid)ui.user=uid;if(id){ui.selected=id;ui.scanRaw=M.qr(M.device(store,id));}scanResult=null;scanError='';scanAdded=false;navigate('mini','scan');}
  function identifyScan(){ui.scanRaw=content.querySelector('#wf-scan-raw').value;try{scanResult=M.inspectScan(store,ui.user,ui.scanRaw);ui.selected=scanResult.device.id;scanError='';}catch(e){scanError=e.message;scanResult=null;}render();save();}
  root.addEventListener('input',function(e){const id=e.target.id;if(id==='wf-mini-search'){ui.query=e.target.value;drawMiniList();}if(id==='wf-admin-search'){ui.adminQuery=e.target.value;drawAdminRows();}if(id==='wf-scan-raw'){ui.scanRaw=e.target.value;}if(id==='wf-contract-phone'){const r=root.querySelector('#wf-owner-result');if(r)r.textContent='手机号已修改，请重新核对用户。';}});
  root.addEventListener('change',function(e){const id=e.target.id;if(id==='wf-demo-user'){ui.user=e.target.value;ui.screen='devices';scanResult=null;scanError='';closeModal();render();save();}if(id==='wf-scan-select'){ui.scanRaw=e.target.value;content.querySelector('#wf-scan-raw').value=ui.scanRaw;}if(id==='wf-perm-device'){const target=e.target.value;e.target.value=ui.selected;leave(()=>navigate('admin','permissions',target));}if(e.target.dataset.perm){const uid=e.target.dataset.permUser,k=e.target.dataset.perm;permissionDraft[uid][k]=e.target.checked;if(k==='view'&&!e.target.checked)M.fields.slice(1).forEach(x=>permissionDraft[uid][x]=false);if(k!=='view'&&e.target.checked)permissionDraft[uid].view=true;M.fields.forEach(x=>{main.querySelector('[data-perm-user="'+uid+'"][data-perm="'+x+'"]').checked=permissionDraft[uid][x];});updatePermissionButton();}});
  root.addEventListener('click',function(e){const b=e.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;try{
    if(data.mode){leave(()=>{closeModal();ui.mode=data.mode;render();save();});return;}
    if(data.page){leave(()=>{if(data.page==='income'){ui.incomeScope=null;ui.incomeFromReport=false;}navigate('admin',data.page);});return;}
    if(data.miniNav){if(data.miniNav==='scan')startScan();else navigate('mini',data.miniNav);return;}
    if(b.id==='im-back'){navigate('mini',['rental','history'].includes(ui.screen)?'detail':ui.screen==='sms'?'profile':'devices');return;}
    if(data.device){navigate('mini','detail',data.device);return;}
    if(data.miniFilter){ui.filter=data.miniFilter;render();save();return;}
    if(data.adminFilter){ui.adminFilter=data.adminFilter;render();save();return;}
    if(data.authorize){leave(()=>navigate('admin','permissions',data.authorize));return;}
    if(data.info){ui.selected=data.info;progress();deviceInfo(data.info);return;}
    if(data.leaseDevice){ui.selected=data.leaseDevice;progress();if(cFor(dNow()))contractDetails(data.leaseDevice);else startContract(data.leaseDevice);return;}
    if(data.contractStart){startContract(data.contractStart);return;}
    if(data.contractDetails){contractDetails(data.contractDetails);return;}
    if(data.renew){renewal(data.renew);return;}
    if(data.ownerScan){const c=M.contract(store,data.ownerScan);startScan(data.ownerScan,c.owner);return;}
    if(data.userScan){startScan(data.userScan);return;}
    if(data.metric){ui.metric=data.metric;render();save();return;}
    if(data.history){ui.historyView=data.history;render();save();return;}
    if(data.command){openCommand(data.command);return;}
    if(data.confirmCommand){executeCommand(data.confirmCommand,undefined,b);return;}
    const a=data.action;
    if(a==='close'){closeModal();return;}
    if(a==='discard-leave'){const action=pendingLeave;permissionDraft=null;permissionDevice=null;closeModal();if(action)action();return;}
    if(a==='scan'){startScan();return;}
    if(a==='scan-identify'||a==='scan-album'){identifyScan();return;}
    if(a==='scan-cancel'||a==='mini-list'){navigate('mini','devices');return;}
    if(a==='scan-again'){scanResult=null;scanError='';scanAdded=false;render();save();return;}
    if(a==='scan-confirm'){const d=M.addByScan(store,ui.user,ui.scanRaw);ui.selected=d.id;scanAdded=true;scanResult=M.inspectScan(store,ui.user,ui.scanRaw);render();save();return;}
    if(a==='scan-open'){navigate('mini','detail',scanResult.device.id);return;}
    if(['rental','history','sms'].includes(a)){navigate('mini',a);return;}
    if(a==='frequency'){openFrequency();return;}
    if(a==='frequency-save'){const v=root.querySelector('#wf-frequency').value;if(v.trim()===''||!Number.isFinite(Number(v))||Number(v)<0||Number(v)>80)throw new Error('请输入 0–80 之间的频率。');executeCommand('frequency',v,b);return;}
    if(a==='inventory'){startInventory();return;}
    if(a==='inventory-parse'){inventoryDraft.raw=root.querySelector('#wf-inventory-qr').value;inventoryDraft.parsed=M.inspectInventory(store,inventoryDraft.raw);inventoryStep(2);return;}
    if(a==='inventory-back'){inventoryDraft.name=root.querySelector('#wf-inventory-name').value;inventoryDraft.place=root.querySelector('#wf-inventory-place').value;inventoryStep(1);return;}
    if(a==='inventory-save'){inventoryDraft.name=root.querySelector('#wf-inventory-name').value;inventoryDraft.place=root.querySelector('#wf-inventory-place').value;const d=M.addInventoryFor(store,'admin',inventoryDraft,'desktop');ui.selected=d.id;ui.scanRaw=M.qr(d);ui.adminFilter='all';ui.adminQuery='';render();save();inventoryStep(3);return;}
    if(a==='new-contract'){startContract();return;}
    if(a==='lookup-owner'){readContract();const u=store.users.find(x=>x.phone===contractDraft.phone.trim());root.querySelector('#wf-owner-result').textContent=u?'已找到：'+u.name+' · '+M.mask(u.phone)+'（微信已绑定）':'未找到已绑定用户，请核对手机号。';fitModal();return;}
    if(a==='contract-review'){readContract();M.validateContract(store,contractDraft);contractStep(2);return;}
    if(a==='contract-back'){contractStep(1);return;}
    if(a==='contract-save'){const c=M.registerContract(store,Object.assign({},contractDraft,{confirmed:root.querySelector('#wf-contract-confirmed').checked}));ui.selected=c.device;render();save();contractStep(3);return;}
    if(a==='review-permissions'){reviewPermissions();return;}
    if(a==='apply-permissions'){const changes=M.grant(store,ui.selected,permissionDraft,root.querySelector('#wf-permission-reason').value);permissionDraft=null;permissionDevice=null;closeModal();render();save();const u=M.user(store,changes[0].uid);modal('admin','授权已生效',dNow().name,'<div class="wf-success"><span>'+icon('shield-check')+'</span><h2>已更新 '+changes.length+' 位用户的权限</h2><p>第一所有人及租赁合同保持不变。</p></div><div class="wf-footer-buttons"><button type="button" class="ia-secondary" data-action="close">返回授权列表</button><button type="button" class="ia-primary" data-preview-user="'+u.id+'">查看 '+u.name+' 的小程序</button></div>');return;}
    if(data.previewUser){ui.user=data.previewUser;navigate('mini',M.can(store,ui.selected,ui.user,'view').ok?'detail':'devices');return;}
    if(a==='renew-save'){M.renew(store,renewDevice,root.querySelector('#wf-renew-end').value,root.querySelector('#wf-renew-paid').value,root.querySelector('#wf-renew-confirmed').checked,root.querySelector('#wf-renew-paidAt').value,root.querySelector('#wf-renew-reference').value);closeModal();render();save();toast('续租已登记，提醒计划已更新，设备不会自动启动。');return;}
  }catch(error){showError(error);}});
  root.addEventListener('keydown',function(e){const layer=!aLayer.hidden?aLayer:!mLayer.hidden?mLayer:null;if(!layer)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const f=Array.from(layer.querySelectorAll('button:not(:disabled),input,select,textarea'));if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f[f.length-1].focus();}else if(!e.shiftKey&&document.activeElement===f[f.length-1]){e.preventDefault();f[0].focus();}}});
  const resize=new ResizeObserver(()=>fitModal());resize.observe(root);
  render();
  if(globalThis.Tweak){const tweak=new Tweak({container:admin,onChange:()=>{admin.style.setProperty('--ia-row-space',ui.density+'px');save();}});tweak.addSlider(ui,'density',{label:'后台表格行间距',min:10,max:22,step:2,unit:'px'});}
})();
